 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    # The distinctive motif color is the least frequent non-background color.
    colors = [c for c in counts if c != 0]
    if not colors:
        return [row[:] for row in grid]
    color = min(colors, key=lambda c: counts[c])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, c0 = min(r for r, c in points), min(c for r, c in points)
    stencil = [(r-r0, c-c0) for r, c in points]
    mh = max(r for r, c in stencil) + 1
    mw = max(c for r, c in stencil) + 1
    out = [row[:] for row in grid]
    for r in range(h-mh+1):
        for c in range(w-mw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in stencil):
                for dr, dc in stencil:
                    out[r+dr][c+dc] = color
    return out
